#!/usr/bin/env node

const fs = require('fs');
const fetch = require('node-fetch').default || require('node-fetch');

// Read CSV data
const csvData = fs.readFileSync('/data/samples/user_activity_sample.csv', 'utf8');
const lines = csvData.trim().split('\n');
const headers = lines[0].split(',');

// Convert CSV to JSON records
const records = [];
for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',');
  if (values.length === headers.length) {
    const record = {
      event_id: values[0],
      event_ts: values[1],
      user_id: values[2],
      action: values[3],
      duration_ms: parseFloat(values[4]) || 0  // Default to 0 for null/undefined
    };
    records.push(record);
  }
}

console.log(`Converted ${records.length} records from CSV`);

// Send records to ingestion API
async function loadData() {
  const promises = records.map(async (record, index) => {
    try {
      const response = await fetch('http://localhost:4000/ingest/UserActivity', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(record)
      });

      if (response.ok) {
        console.log(`✓ Record ${index + 1} loaded: ${record.event_id}`);
      } else {
        const error = await response.text();
        console.error(`✗ Record ${index + 1} failed: ${error}`);
      }
    } catch (error) {
      console.error(`✗ Record ${index + 1} error:`, error.message);
    }
  });

  await Promise.all(promises);
  console.log('Data loading completed!');
}

// Execute the loading
loadData().catch(console.error);

